// Base64画像をバイナリデータに変換してGoogle Driveアップロード用に準備
const base64Data = $json.image_base64;
const binaryData = Buffer.from(base64Data, 'base64');

return {
  json: {
    section: $json.section,
    duration: $json.duration,
    filename: $json.filename,
    motion_prompt: $json.motion_prompt,
    text: $json.text,
    image_base64: $json.image_base64
  },
  binary: {
    data: {
      data: binaryData.toString('base64'),
      mimeType: 'image/png',
      fileName: $json.filename,
      fileExtension: 'png'
    }
  }
};

// Google Driveアップロードのレスポンスとスライドメタデータをマージ
const driveResponse = $input.first().json;
const slideMetadata = $('Code - Convert to Binary').item.json;

let imageUrl = null;
if (driveResponse.id && !driveResponse.error) {
  imageUrl = `https://drive.google.com/uc?export=download&id=${driveResponse.id}`;
}

return {
  json: {
    section: slideMetadata.section || '',
    duration: slideMetadata.duration || 0,
    motion_prompt: slideMetadata.motion_prompt || '',
    image_url: imageUrl,
    text: slideMetadata.text || ''
  }
};

// Phase4bへの入力データを準備
const scriptId = $('Notion - Get Script Data').first().json.id;
const slidesMetadata = $json.data || [];

if (!scriptId) {
  throw new Error('script_id is required');
}

if (!slidesMetadata || slidesMetadata.length !== 7) {
  throw new Error('slides_metadata must contain exactly 7 items');
}

// 各スライドの必須フィールド確認
for (const slide of slidesMetadata) {
  if (!slide.image_url) throw new Error(`Missing image_url for ${slide.section}`);
  if (slide.duration === undefined || slide.duration === null) throw new Error(`Missing duration for ${slide.section}`);
  // motion_promptは空文字列でも許可（デフォルト値が設定されるため）
  if (slide.motion_prompt === undefined || slide.motion_prompt === null) throw new Error(`Missing motion_prompt for ${slide.section}`);
}

return {
  json: {
    script_id: scriptId,
    slides_metadata: slidesMetadata
  }
};

// 現在処理中のスライド（各アイテムごとに実行）
const slide = $input.item.json;
const scriptId = $('Code - Validate Input for Phase4b').item.json.script_id;

// FAL Compose APIペイロード構築
const payload = {
  tracks: [
    {
      id: "1",
      type: "video",
      keyframes: [
        {
          url: slide.image_url,
          timestamp: 0,
          duration: slide.duration
        }
      ]
    }
  ]
};

return {
  json: {
    fal_payload: JSON.stringify(payload),
    slide_metadata: slide,
    script_id: scriptId,
    slide_index: $itemIndex
  }
};

const resultData = $input.item.json;
const slideData = $('Code - Prepare FAL Payload').item.json.slide_metadata;
const requestId = $('HTTP Request - Submit to FAL').item.json.request_id;
const slideIndex = $('Code - Prepare FAL Payload').item.json.slide_index;
const scriptId = $('Code - Prepare FAL Payload').item.json.script_id;

// video_url抽出
const videoUrl = resultData.output?.video_url 
  || resultData.video_url 
  || resultData.result?.video_url;

if (!videoUrl) {
  throw new Error('Video URL not found in FAL API response');
}

// videos_metadataオブジェクト構築
return {
  json: {
    section: slideData.section,
    duration: slideData.duration,
    video_url: videoUrl,
    fal_request_id: requestId,
    motion_prompt: slideData.motion_prompt,
    filename: `video_${slideIndex + 1}_${slideData.section}.mp4`,
    text: slideData.text,
    slide_index: slideIndex,
    script_id: scriptId
  }
};

const slide = $input.first().json.slide_metadata;
const retryCount = $input.first().json.retry_count;

return {
  json: {
    success: false,
    error: `Rendering timeout for ${slide.section} after ${retryCount} retries`,
    section: slide.section,
    retry_count: retryCount
  }
};

const allItems = $input.all();

// Aggregateノードからの出力を取得
const aggregatedData = allItems[0]?.json?.data || [];

// 最初のアイテムからscript_idを取得
const scriptId = aggregatedData[0]?.script_id || 'unknown';

// videos_metadata配列を構築（sectionの順序でソート）
const sectionOrder = ['hook', 'intro', 'point1', 'point2', 'point3', 'summary', 'cta'];

const videosMetadata = aggregatedData
  .filter(item => item.video_url) // video_urlがあるもののみ
  .sort((a, b) => {
    return sectionOrder.indexOf(a.section) - sectionOrder.indexOf(b.section);
  });

return {
  json: {
    success: true,
    script_id: scriptId,
    videos_metadata: videosMetadata,
    videos_count: videosMetadata.length,
    total_duration: videosMetadata.reduce((sum, v) => sum + v.duration, 0)
  }
};
